const CHECK_LEFT_CLIP = '100,150 353,150 353,514 396,583 396,700 100,700';

// Emblem occupies x 88–720, y 194–694 in source coordinates; wordmark x 612–1494, y 250–716.
const EMBLEM_BOX = { x: 88, y: 194, w: 632, h: 500 };

function Grads({ p, names }: { p: string; names: string[] }) {
  return (
    <>
      {names.map((n) => {
        const g = GRAD[n];
        return (
          <linearGradient key={n} id={`${p}${n}`} gradientUnits="userSpaceOnUse" x1={g.x1} y1={g.y1} x2={g.x2} y2={g.y2}>
            {g.stops.map(([o, c], i) => (
              <stop key={i} offset={o} stopColor={c} />
            ))}
          </linearGradient>
        );
      })}
    </>
  );
}

const EMBLEM_GRADS = ['bar', 'left', 'right', 'windows', 'dome', 'swoosh', 'ckL', 'ckR'];
const WORD_GRADS = ['veridian', 'hms', 'ecg', 'leaf', 'tagline'];

function EmblemDefs({ p }: { p: string }) {
  return (
    <>
      <Grads p={p} names={EMBLEM_GRADS} />
      <clipPath id={`${p}clL`}><rect x="0" y="0" width="224" height="800" /></clipPath>
      <clipPath id={`${p}clR`}><rect x="431" y="0" width="400" height="800" /></clipPath>
      <clipPath id={`${p}clCk`}><polygon points={CHECK_LEFT_CLIP} /></clipPath>
    </>
  );
}

function EmblemShapes({ p }: { p: string }) {
  const u = (n: string) => `url(#${p}${n})`;
  return (
    <>
      <path d={PATH.swoosh} fill={u('swoosh')} fillRule="evenodd" />
      {/* white plate: keeps the building and the check outline white on any background */}
      <g fill="#fff">
        <rect x="225" y="199" width="206" height="423" rx="32" />
        <rect x="93" y="332" width="457" height="164" rx="32" />
      </g>
      <path d={PATH.cross} fill={u('bar')} fillRule="evenodd" />
      <path d={PATH.cross} fill={u('left')} fillRule="evenodd" clipPath={`url(#${p}clL)`} />
      <path d={PATH.cross} fill={u('right')} fillRule="evenodd" clipPath={`url(#${p}clR)`} />
      <path d={PATH.windows} fill={u('windows')} fillRule="evenodd" />
      <path d={PATH.dome} fill={u('dome')} fillRule="evenodd" />
      <path d={PATH.check} fill={u('ckR')} fillRule="evenodd" />
      <path d={PATH.check} fill={u('ckL')} fillRule="evenodd" clipPath={`url(#${p}clCk)`} />
    </>
  );
}

function WordmarkShapes({ p, dark, tagline }: { p: string; dark: boolean; tagline: boolean } ) {
  const u = (n: string) => `url(#${p}${n})`;
  return (
    <>
      <path d={PATH.veridian} fill={dark ? '#FFFFFF' : u('veridian')} fillRule="evenodd" />
      <path d={PATH.leaf} fill={u('leaf')} fillRule="evenodd" />
      <path d={PATH.hms} fill={u('hms')} fillRule="evenodd" />
      <path d={PATH.ecg} fill={u('ecg')} fillRule="evenodd" />
      {tagline && <path d={PATH.tagline} fill={dark ? '#A8C4D8' : u('tagline')} fillRule="evenodd" />}
    </>
  );
}

export default function VeridianLogo({
  size = 32,
  className,
  variant = 'full',
  dark = false,
  tagline = true,
}: VeridianLogoProps) {
  const uid = useId().replace(/[^a-zA-Z0-9]/g, '');
  const p = `vh${uid}-`;
  const common = {
    className,
    fill: 'none' as const,
    xmlns: 'http://www.w3.org/2000/svg',
    style: { display: 'block', flexShrink: 0 },
  };

  if (variant === 'emblem') {
    const { x, y, w, h } = EMBLEM_BOX;
    return (
      <svg {...common} width={(size * w) / h} height={size} viewBox={`${x} ${y} ${w} ${h}`} aria-hidden="true" focusable="false">
        <defs><EmblemDefs p={p} /></defs>
        <EmblemShapes p={p} />
      </svg>
    );
  }

  if (variant === 'stacked') {
    // wordmark sits under the emblem, centred on it
    const VB = { x: 604, y: 194, w: 896, h: 992 };
    const height = (size * VB.h) / EMBLEM_BOX.h;
    return (
      <svg {...common} width={(height * VB.w) / VB.h} height={height} viewBox={`${VB.x} ${VB.y} ${VB.w} ${VB.h}`} role="img" aria-label="Veridian HMS">
        <defs><EmblemDefs p={p} /><Grads p={p} names={WORD_GRADS} /></defs>
        <g transform="translate(648.5 0)"><EmblemShapes p={p} /></g>
        <g transform="translate(0 470)"><WordmarkShapes p={p} dark={dark} tagline={tagline} /></g>
      </svg>
    );
  }

  const VB = { x: 88, y: 194, w: 1406, h: 522 };
  const height = (size * VB.h) / EMBLEM_BOX.h;
  return (
    <svg {...common} width={(height * VB.w) / VB.h} height={height} viewBox={`${VB.x} ${VB.y} ${VB.w} ${VB.h}`} role="img" aria-label="Veridian HMS">
      <defs><EmblemDefs p={p} /><Grads p={p} names={WORD_GRADS} /></defs>
      <EmblemShapes p={p} />
      <WordmarkShapes p={p} dark={dark} tagline={tagline} />
    </svg>
  );
}